package bits.dao;
import bits.database.DBConnection; import bits.model.Component; import java.sql.*; import java.util.*;
public class ComponentDAO {
 public List<Component> list(int userId,String search)throws SQLException{List<Component> out=new ArrayList<>();String q="SELECT c.id,COALESCE(c.category_id,0) category_id,c.name,c.component_value,c.quantity,COALESCE(cat.name,'Uncategorised') category,c.location,c.notes FROM components c LEFT JOIN categories cat ON c.category_id=cat.id WHERE c.user_id=? AND (c.name LIKE ? OR c.component_value LIKE ? OR COALESCE(cat.name,'') LIKE ? OR c.location LIKE ?) ORDER BY c.name";try(Connection cn=DBConnection.getConnection();PreparedStatement p=cn.prepareStatement(q)){p.setInt(1,userId);String s="%"+(search==null?"":search.trim())+"%";for(int i=2;i<=5;i++)p.setString(i,s);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Component(r.getInt("id"),r.getInt("category_id"),r.getString("name"),r.getString("component_value"),r.getInt("quantity"),r.getString("category"),r.getString("location"),r.getString("notes")));}}return out;}
 public void save(int userId,int id,int categoryId,String name,String value,int quantity,String location,String notes)throws SQLException{if(id==0){String q="INSERT INTO components(user_id,category_id,name,component_value,quantity,location,notes) VALUES(?,?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){bind(p,userId,categoryId,name,value,quantity,location,notes,0);p.executeUpdate();}}else{String q="UPDATE components SET category_id=?,name=?,component_value=?,quantity=?,location=?,notes=? WHERE id=? AND user_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setObject(1,categoryId==0?null:categoryId);p.setString(2,name.trim());p.setString(3,value);p.setInt(4,quantity);p.setString(5,location);p.setString(6,notes);p.setInt(7,id);p.setInt(8,userId);p.executeUpdate();}}}
 private void bind(PreparedStatement p,int uid,int cid,String n,String v,int qty,String loc,String notes,int unused)throws SQLException{p.setInt(1,uid);p.setObject(2,cid==0?null:cid);p.setString(3,n.trim());p.setString(4,v);p.setInt(5,qty);p.setString(6,loc);p.setString(7,notes);}
 public void changeQuantity(int userId,int id,int delta)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE components SET quantity=GREATEST(0,quantity+?) WHERE id=? AND user_id=?")){p.setInt(1,delta);p.setInt(2,id);p.setInt(3,userId);p.executeUpdate();}}
 public void delete(int userId,int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM components WHERE id=? AND user_id=?")){p.setInt(1,id);p.setInt(2,userId);p.executeUpdate();}}
}
